// KanjiDB v2 loader — lazy access to the full kanji database generated by
// scripts/build-kanjidb.mjs into public/data/kanjidb/.
//
// Layout (see docs/18-Kanji-Database.md for the full spec):
//   index.json                 one compact row per KANJIDIC2 kanji (13,108)
//   meta/meta-{s}.json         full metadata shards;  s = hex(codepoint >> 10)
//   strokes/strokes-{s}.json   KanjiVG stroke paths + component trees;
//                              s = hex(codepoint >> 8)
//   components.json            component element -> [kanjiChars, primaryOn]
//   radicals.json              the 214 Kangxi radicals with provenance
//   manifest.json              counts, shard maps, validation results
//
// Everything is fetched lazily and cached per shard, so opening one kanji
// costs one small shard download, never the whole database. A kanji with no
// KanjiVG entry returns an honest null from getKanjiStrokes — never a fake.

const BASE = '/data/kanjidb'

// ------------------------------------------------------------- shard maths
export function metaShardFor(char) {
  return (char.codePointAt(0) >> 10).toString(16)
}
export function strokesShardFor(char) {
  return (char.codePointAt(0) >> 8).toString(16)
}
export function metaShardPath(char) {
  return `${BASE}/meta/meta-${metaShardFor(char)}.json`
}
export function strokesShardPath(char) {
  return `${BASE}/strokes/strokes-${strokesShardFor(char)}.json`
}

// ------------------------------------------------------------------ caches
const shardCache = new Map()
function fetchShard(path) {
  if (!shardCache.has(path)) {
    shardCache.set(
      path,
      fetch(path).then((r) => (r.ok ? r.json() : null)).catch(() => null),
    )
  }
  return shardCache.get(path)
}
let indexPromise = null
let componentsPromise = null
let radicalsPromise = null
let manifestPromise = null

// ------------------------------------------------------------- index/search
// Index rows are arrays: [char, cp, on, kun, meaning, strokes, freq, grade,
// jlpt, radical]. Expand once into objects for consumers.
export function expandIndexRow(row) {
  const [char, cp, on, kun, meaning, strokes, freq, grade, jlpt, radical] = row
  return { char, cp, on, kun, meaning, strokes, freq, grade, jlpt, radical }
}

export function loadKanjiIndex() {
  if (!indexPromise) {
    indexPromise = fetch(`${BASE}/index.json`)
      .then((r) => (r.ok ? r.json() : []))
      .then((rows) => rows.map(expandIndexRow))
      .catch(() => [])
  }
  return indexPromise
}

const HIRA_TO_KATA = (s) => s.replace(/[ぁ-ん]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x60))

// Minimal Hepburn romaji for katakana strings — search aid only, so a
// learner typing "go" or "kataru" finds ゴ / かた(る). Not a transliteration
// of record; readings of record are the kana themselves.
const KANA_ROMAJI = {
  ア: 'a', イ: 'i', ウ: 'u', エ: 'e', オ: 'o', カ: 'ka', キ: 'ki', ク: 'ku', ケ: 'ke', コ: 'ko',
  サ: 'sa', シ: 'shi', ス: 'su', セ: 'se', ソ: 'so', タ: 'ta', チ: 'chi', ツ: 'tsu', テ: 'te', ト: 'to',
  ナ: 'na', ニ: 'ni', ヌ: 'nu', ネ: 'ne', ノ: 'no', ハ: 'ha', ヒ: 'hi', フ: 'fu', ヘ: 'he', ホ: 'ho',
  マ: 'ma', ミ: 'mi', ム: 'mu', メ: 'me', モ: 'mo', ヤ: 'ya', ユ: 'yu', ヨ: 'yo',
  ラ: 'ra', リ: 'ri', ル: 'ru', レ: 're', ロ: 'ro', ワ: 'wa', ヰ: 'wi', ヱ: 'we', ヲ: 'wo', ン: 'n',
  ガ: 'ga', ギ: 'gi', グ: 'gu', ゲ: 'ge', ゴ: 'go', ザ: 'za', ジ: 'ji', ズ: 'zu', ゼ: 'ze', ゾ: 'zo',
  ダ: 'da', ヂ: 'ji', ヅ: 'zu', デ: 'de', ド: 'do', バ: 'ba', ビ: 'bi', ブ: 'bu', ベ: 'be', ボ: 'bo',
  パ: 'pa', ピ: 'pi', プ: 'pu', ペ: 'pe', ポ: 'po', ヴ: 'vu',
  ァ: 'a', ィ: 'i', ゥ: 'u', ェ: 'e', ォ: 'o', ャ: 'ya', ュ: 'yu', ョ: 'yo', ヮ: 'wa', ッ: '', ー: '',
}
const COMBO_ROMAJI = {
  キャ: 'kya', キュ: 'kyu', キョ: 'kyo', シャ: 'sha', シュ: 'shu', ショ: 'sho',
  チャ: 'cha', チュ: 'chu', チョ: 'cho', ニャ: 'nya', ニュ: 'nyu', ニョ: 'nyo',
  ヒャ: 'hya', ヒュ: 'hyu', ヒョ: 'hyo', ミャ: 'mya', ミュ: 'myu', ミョ: 'myo',
  リャ: 'rya', リュ: 'ryu', リョ: 'ryo', ギャ: 'gya', ギュ: 'gyu', ギョ: 'gyo',
  ジャ: 'ja', ジュ: 'ju', ジョ: 'jo', ヂャ: 'ja', ヂュ: 'ju', ヂョ: 'jo',
  ビャ: 'bya', ビュ: 'byu', ビョ: 'byo', ピャ: 'pya', ピュ: 'pyu', ピョ: 'pyo',
}
export function kanaToRomaji(kana) {
  const kata = HIRA_TO_KATA(String(kana || ''))
  let out = ''
  let prevVowel = ''
  for (let i = 0; i < kata.length; i++) {
    const two = kata.slice(i, i + 2)
    if (COMBO_ROMAJI[two]) {
      out += COMBO_ROMAJI[two]
      prevVowel = out.slice(-1)
      i++
      continue
    }
    const ch = kata[i]
    if (ch === 'ッ') {
      const next = COMBO_ROMAJI[kata.slice(i + 1, i + 3)] || KANA_ROMAJI[kata[i + 1]] || ''
      if (next) out += next[0]
      continue
    }
    if (ch === 'ー') {
      out += prevVowel
      continue
    }
    const roma = KANA_ROMAJI[ch]
    if (roma) {
      out += roma
      prevVowel = out.slice(-1)
    }
  }
  return out
}

/**
 * Pure search over expanded index rows. Matches, in rank order:
 * the character itself; kana readings (hiragana or katakana, okurigana
 * ignored); romaji of the readings; English meaning (substring).
 */
export function searchIndex(rows, query, limit = 50) {
  const q = String(query || '').trim()
  if (!q) return []
  const qKata = HIRA_TO_KATA(q)
  const qLower = q.toLowerCase()
  const hits = []
  for (const row of rows) {
    let score = -1
    if (row.char === q) score = 0
    else if (q.length === 1 && row.char.includes(q)) score = 1
    if (score < 0) {
      const readings = `${row.on}・${row.kun}`.replace(/[()]/g, '')
      if (HIRA_TO_KATA(readings).includes(qKata) && /[ぁ-んァ-ヶ]/.test(q)) score = 2
      else if (/^[a-z]+$/.test(qLower)) {
        const romaji = kanaToRomaji(row.on) + ' ' + kanaToRomaji(row.kun.replace(/[()]/g, ''))
        if (romaji.split(/[\s・]+/).some((r) => r === qLower)) score = 3
        else if (row.meaning.toLowerCase().includes(qLower)) score = 4
      } else if (row.meaning.toLowerCase().includes(qLower)) score = 4
    }
    if (score >= 0) hits.push({ score, row })
  }
  hits.sort((a, b) => a.score - b.score || (a.row.freq ?? 99999) - (b.row.freq ?? 99999))
  return hits.slice(0, limit).map((h) => h.row)
}

export async function searchKanji(query, limit = 50) {
  const rows = await loadKanjiIndex()
  return searchIndex(rows, query, limit)
}

// ------------------------------------------------------------ meta + strokes
export async function getKanjiMeta(char) {
  const shard = await fetchShard(metaShardPath(char))
  return shard?.[char] || null
}

// Compact tree nodes from the generator use short keys; expand to the
// documented friendly shape. Direct strokes only — a component's full
// stroke set is the union over its subtree (see subtreeStrokeIndices).
export function expandTree(node) {
  if (!node) return null
  return {
    element: node.e ?? null,
    radical: node.r ?? null,
    position: node.p ?? null,
    phon: node.ph ?? null,
    part: node.pt ?? null,
    original: node.o ?? null,
    variant: Boolean(node.v),
    children: (node.c || []).map(expandTree),
    strokes: [...(node.s || [])],
  }
}
export function expandStrokesEntry(entry) {
  if (!entry) return null
  return { paths: entry.paths, tree: expandTree(entry.tree) }
}
export function subtreeStrokeIndices(node) {
  if (!node) return []
  const out = [...(node.strokes || [])]
  for (const child of node.children || []) out.push(...subtreeStrokeIndices(child))
  return out.sort((a, b) => a - b)
}

/** { paths, tree } for the kanji, or null when KanjiVG has no entry. */
export async function getKanjiStrokes(char) {
  const shard = await fetchShard(strokesShardPath(char))
  return expandStrokesEntry(shard?.[char] || null)
}

// ------------------------------------------------------- components/radicals
export function loadComponents() {
  if (!componentsPromise) {
    componentsPromise = fetch(`${BASE}/components.json`)
      .then((r) => (r.ok ? r.json() : {}))
      .catch(() => ({}))
  }
  return componentsPromise
}

/** All kanji whose KanjiVG tree contains the component (related kanji). */
export async function kanjiWithComponent(component) {
  const components = await loadComponents()
  const entry = components[component]
  return entry ? [...entry[0]] : []
}

/** The component's own primary on-reading when it is itself a kanji. */
export async function componentOnReading(component) {
  const components = await loadComponents()
  return components[component]?.[1] || ''
}

export function getRadicals() {
  if (!radicalsPromise) {
    radicalsPromise = fetch(`${BASE}/radicals.json`)
      .then((r) => (r.ok ? r.json() : []))
      .catch(() => [])
  }
  return radicalsPromise
}

export function loadManifest() {
  if (!manifestPromise) {
    manifestPromise = fetch(`${BASE}/manifest.json`)
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null)
  }
  return manifestPromise
}
